import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Kanuni za Maadili za Kati ya Ndege","description":"","frontmatter":{},"headers":[],"relativePath":"sw/88-跨位面伦理准则.md","filePath":"sw/88-跨位面伦理准则.md"}'),t={name:"sw/88-跨位面伦理准则.md"};function e(w,a,l,m,h,o){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="kanuni-za-maadili-za-kati-ya-ndege" tabindex="-1">Kanuni za Maadili za Kati ya Ndege <a class="header-anchor" href="#kanuni-za-maadili-za-kati-ya-ndege" aria-label="Permalink to &quot;Kanuni za Maadili za Kati ya Ndege&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>88</td></tr><tr><td>Moduli</td><td>Mwingiliano wa Kati ya Ndege na Kanuni za Wakati</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Maadili ya kati ya ndege, uhuru wa ustaarabu, kutopinga kuingilia, heshima ya kitamaduni, ubalozi wa symbiosis</td></tr></tbody></table><h2 id="_1-msingi-wa-kifalsafa-wa-kanuni-za-maadili" tabindex="-1">1. Msingi wa Kifalsafa wa Kanuni za Maadili <a class="header-anchor" href="#_1-msingi-wa-kifalsafa-wa-kanuni-za-maadili" aria-label="Permalink to &quot;1. Msingi wa Kifalsafa wa Kanuni za Maadili&quot;">​</a></h2><p>Kanuni za maadili za kati ya ndege ni kanuni za maadili na mifumo ya tabia ambayo ustaarabu wa symbiosis wa nanga lazima uzifuate wakati wa kuingiliana na ustaarabu wa ndege nyingine. Msingi wake wa kifalsafa ni kanuni ya &quot;ubinafsi wa ustaarabu&quot; — kila ustaarabu wa ndege, bila kujali kiwango cha maendeleo yake chake au juu, umbo la rangi yake, au mfumo wa kijamii wake, una ubinafsi usioweza kutolewa na haki ya maendeleo ya kujitegemea. Ustaarabu wowote wa kigeni hawezi, kwa sababu yoyote, kuondoa ubinafsi huu, au kulazimisha mapenzi yake mwenyewe kwa ustaarabu mwingine.</p><p>Uanzishwaji wa msingi huu wa kifalsafa unafuata mfululizo wa wazo la msingi la &quot;kupinga mauaji&quot; wa ustaarabu wa symbiosis wa nanga. Sifa ya msingi ya ustaarabu wa mauaji ni kutokutambua ubinafsi wa ustaarabu mwingine, na kumtambua ustaarabu mwingine kama rasilimali inayoweza kutumika au kipengele kinachoweza kushindwa. Ili ustaarabu wa symbiosis wa nanga uzidi kwa kweli ustaarabu wa mauaji, lazima aache kabisa hii mtazamo katika mwingiliano wa kati ya ndege, na kushirikiana na kila ustaarabu anayekutana naye kwa mtazamo wa usawa, heshima, na symbiosis.</p><p>Upeo wa ufanisi wa kanuni za maadili za kati ya ndege unajumuisha tabia zote za mwingiliano wa kati ya ndege, ikiwa ni pamoja na lakini haiwezi kufikiwa: kuvuka ndege, mawasiliano ya kati ya ndege, shughuli za kichunguzi, biashara, ubadilishaji wa kitamaduni, ushirikiano wa kiufundi, na kuingilia kimaadili katika hali ya dharura. Shirikishi na mtu yeyote anapotekeleza mwingiliano wa kati ya ndege lazima atii masharti yote ya kanuni hii.</p><h2 id="_2-kanuni-sita-za-maadili" tabindex="-1">2. Kanuni Sita za Maadili <a class="header-anchor" href="#_2-kanuni-sita-za-maadili" aria-label="Permalink to &quot;2. Kanuni Sita za Maadili&quot;">​</a></h2><p>Kanuni za maadili za kati ya ndege zinajumuisha kanuni sita za msingi, na zinatumika mfumo kamili wa maadili ya thamani:</p><table tabindex="0"><thead><tr><th>Kanuni</th><th>Maudhui ya Msingi</th><th>Mahitaji Mahususi</th></tr></thead><tbody><tr><td>Kanuni ya Uhuru wa Ustaarabu</td><td>Kuheshimu haki ya maendeleo ya kujitegemea ya ustaarabu wa ndege lengwa, kutopinga kuingilia kwa kulazimisha katika mambo yake ya ndani</td><td>Hufai kulazimisha kubadilisha mfumo wa kijamii, ideology, na njia ya maendeleo ya ustaarabu lengwa; hufai kukuza wakala au serikali ya傀儡 ndani ya ustaarabu lengwa</td></tr><tr><td>Kanuni ya Kutoingilia</td><td>Isipokuwa ustaarabu lengwa ukabiliwa na msongo wa kiwango cha kutoweka na kuomba kwa shauku msaada, vinginevyo hufanyiwi kuingilia kweli yoyote</td><td>Hufai kuingilia katika migogoro ya ndani ya ustaarabu lengwa; hufai kutoa silaha au msaada wa kijeshi kwa upande wowote wa ustaarabu lengwa; hufai kudhibiti maoni ya umma na mchakato wa kisiasa wa ustaarabu lengwa</td></tr><tr><td>Kanuni ya Heshima ya Kitamaduni</td><td>Kuheshimu desturi za kitamaduni, imani za kidini, na mila za ustaarabu lengwa</td><td>Hufai kufanya tathmini ya ubaguzi au kichekesho cha uovu kwa utamaduni wa ustaarabu lengwa; hufai kulazimisha kutoa bidhaa za kitamaduni na thamani za ndege ya mwenyewe; hufai kufanya ujumuishaji wa kitamaduni kwa jina la &quot;ustaarabu&quot;</td></tr><tr><td>Kanuni ya Usawa na Manufaa ya Pamoja</td><td>Mwingiliano wa kati ya ndege lazima ujengwe kwenye msingi wa usawa, kuhakikisha kuwa pande zote zinaweza kupata manufaa kutoka kwa mwingiliano</td><td>Hufai kutumia ubora wa kiufundi kufanya biashara isiyo sawa; hufai kunyang&#39;anya rasilimali za ustaarabu lengwa; usafirishaji wa kiufundi lazima uzingatie uwezo wa kukubali na athari za kijamii za ustaarabu lengwa</td></tr><tr><td>Kanuni ya Athari Ndogo Zaidi</td><td>Mwingiliano wa kati ya ndege unapaswa kupunguza athari za nje kwa ustaarabu lengwa kadri yawezekanavyo</td><td>Kipaumbele kwa njia za mwingiliano za mawasiliano ya chini na kuingilia chini; upeo na kasi ya shughuli za mwingiliano lazima zidhibitiwe kwa mkali ndani ya mipaka inayohitajika; baada ya mwingiliano kumaliza, lazima tathminiwa na kuondolewa athari za ziada zilizobaki</td></tr><tr><td>Kanuni ya Uwajibikaji</td><td>Tabia zote za mwingiliano wa kati ya ndege lazima ziwe zinazoweza kufuatwa, kuzingatiwa, na kujibiwa</td><td>Kujenga rekodi za kamili za mwingiliano na kumbukumbu; kuanzisha shirika la kujitegemea la ufuatiliaji wa maadili; kuchunguza na kuponya tabia zinazovunja kanuni za maadili</td></tr></tbody></table><p>Kuna uhusiano wa kimantiki ndani kati ya kanuni sita: kanuni ya uhuru wa ustaarabu ni thamani ya msingi, kanuni ya kutoingilia ni mahitaji ya msingi, kanuni ya heshima ya kitamaduni ni udhihirisho wa kiwango cha kitamaduni, kanuni ya usawa na manufaa ya pamoja ni dhamana ya kiwango cha kiuchumi, kanuni ya athari ndogo zaidi ni kanuni ya kiwango cha utekelezaji, na kanuni ya uwajibikaji ni kizuizi cha kiwango cha taasisi. Sita pamoja zinatumika mzunguko kamili wa maadili wa &quot;thamani—mahitaji—udhihirisho—dhamana—kanuni—kizuizi&quot;.</p><h2 id="_3-kanuni-za-maadili-kwa-mazingira-anuwai-ya-mwingiliano" tabindex="-1">3. Kanuni za Maadili kwa Mazingira Anuwai ya Mwingiliano <a class="header-anchor" href="#_3-kanuni-za-maadili-kwa-mazingira-anuwai-ya-mwingiliano" aria-label="Permalink to &quot;3. Kanuni za Maadili kwa Mazingira Anuwai ya Mwingiliano&quot;">​</a></h2><h3 id="_3-1-kanuni-za-maadili-kwa-mazingira-ya-kichunguzi" tabindex="-1">3.1 Kanuni za Maadili kwa Mazingira ya Kichunguzi <a class="header-anchor" href="#_3-1-kanuni-za-maadili-kwa-mazingira-ya-kichunguzi" aria-label="Permalink to &quot;3.1 Kanuni za Maadili kwa Mazingira ya Kichunguzi&quot;">​</a></h3><p>Kichunguzi cha kati ya ndege ni moja ya mazingira ya kawaida za mwingiliano, na msingi wa kanuni zake za maadili ni &quot;kutovuruga&quot;. Timu ya kichunguzi lazima ifuate kwa mkali mpango wa kawaida wa kioo cha nakala + nafasi iliyotengwa + kurudisha maarifa tu, kuhakikisha kuwa mchakato wa kichunguzi hautahisiwa na ustaarabu lengwa. Kwa ndege ambazo bado zina ustaarabu hai, upeo wa kichunguzi lazima ukomeshwe kwa mkali katika maeneo ya mabaki yaliyotolewa, na hufai kufanya skana au nakala ya aina yoyote kwa maeneo ya makazi ya ustaarabu hai.</p><p>Maarifa ya ugunduzi wa kichunguzi wakati wa kurudishwa na kuchapishwa lazima yaheshimu unyeti wa kitamaduni wa ustaarabu lengwa. Ikiwa ugunduzi wa kichunguzi unahusisha vifaa takatifu vya kidini, mabaki ya mababu, au vizuizi vya kitamaduni vya ustaarabu lengwa, taarifa zinazohusika lazima zipitie uchunguzi wa unyeti wa kitamaduni wa Kamati ya Maadili ya Kati ya Ndege kabla ya kuchapishwa, na ikihitajika kufanya mchakato wa kuficha maelezo ya unyeti.</p><h3 id="_3-2-kanuni-za-maadili-kwa-mazingira-ya-mawasiliano" tabindex="-1">3.2 Kanuni za Maadili kwa Mazingira ya Mawasiliano <a class="header-anchor" href="#_3-2-kanuni-za-maadili-kwa-mazingira-ya-mawasiliano" aria-label="Permalink to &quot;3.2 Kanuni za Maadili kwa Mazingira ya Mawasiliano&quot;">​</a></h3><p>Mawasiliano ya kati ya ndege ni njia ya kubadilishana moja kwa moja na ustaarabu lengwa, na msingi wa kanuni zake za maadili ni &quot;ukweli na heshima&quot;. Maudhui ya mawasiliano lazima yawe ya kweli, hufai kutoa kwa makudi taarifa za uwongo au kufanya utangazaji wa udanganyifu; sauti ya mawasiliano lazima iwe sawa, hufai kuwa na mtazamo wa juu dhidi ya ustaarabu wenye kiwango cha maendeleo cha chini; mada ya mawasiliano lazima ipitie ridhaa ya ustaarabu lengwa, hufai kulazimisha kutuma ideology au imani za kidini za ndege ya mwenyewe.</p><p>Wakati wa kuanzisha mawasiliano kwa mara ya kwanza na ustaarabu usiojulikana, lazima ufuate kanuni ya &quot;mawasiliano ya hatua kwa hatua&quot;: kwanza tumia ishara za hisabati na fizikia za kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati ya kati, kisha kupanua upeo wa ubadilishaji kwa hatua kulingana na majibu ya upande mwingine, na hufai kutuma taarifa za kitamaduni au kiufundi tata katika mawasiliano ya kwanza.</p><h3 id="_3-3-kanuni-za-maadili-kwa-mazingira-ya-biashara" tabindex="-1">3.3 Kanuni za Maadili kwa Mazingira ya Biashara <a class="header-anchor" href="#_3-3-kanuni-za-maadili-kwa-mazingira-ya-biashara" aria-label="Permalink to &quot;3.3 Kanuni za Maadili kwa Mazingira ya Biashara&quot;">​</a></h3><p>Msingi wa kanuni za maadili za biashara ya kati ya ndege ni &quot;haki na uendelevu&quot;. Biashara lazara ijengwe kwenye msingi wa hiari ya pande zote, hufai kutumia usawa wa taarifa au ubora wa kiufundi kufanya biashara ya kulazimisha; bei ya biashara lazima iwe ya haki, hufai kufanya bei ya mauaji; bidhaa za biashara hazifai kuwa na maudhui yanayoweza kusababisha msongo wa kijamii au uharibifu wa mazingira kwa ustaarabu lengwa.</p><p>Kinachohitajika kuzingatia kwa pekee ni kwamba biashara ya kati ya ndege ya teknolojia ya uboreshaji na silaha za nishati juu inakabiliwa na vizuizi vya maadili vikali zaidi. Kuusafirisha teknolojia ya uboreshaji ya juu kwa ustaarabu wenye kiwango cha maendeleo cha chini kunaweza kusababisha usawa wa mfumo wa kijamii na kuzidisha migogoro ya ndani; kuusafirisha silaha kunaweza kusababisha moja kwa moja vita. Kwa hivyo, aina hii mbili ya biashara kwa kanuni inakatazwa, na inaweza kufanywa katika hali maalum zaidi tu baada ya kupitia uidhinishaji wa mkutano kamili wa Baraza la Nanga.</p><h3 id="_3-4-kanuni-za-maadili-kwa-mazingira-ya-kuingilia-kwa-dharura" tabindex="-1">3.4 Kanuni za Maadili kwa Mazingira ya Kuingilia kwa Dharura <a class="header-anchor" href="#_3-4-kanuni-za-maadili-kwa-mazingira-ya-kuingilia-kwa-dharura" aria-label="Permalink to &quot;3.4 Kanuni za Maadili kwa Mazingira ya Kuingilia kwa Dharura&quot;">​</a></h3><p>Wakati ustaarabu wa ndege lengwa ukabiliwa na msongo wa kiwango cha kutoweka (kama vile mgongano wa asteroid, janga kubwa la magonjwa, kuanguka kwa sheria), ustaarabu wa symbiosis wa nanga unaweza kufanya kuingilia kimaadili. Lakini hata katika hali kama hii ya dharura, lazima ufuate kanuni zifuatazo za maadili:</p><ul><li>Kabla ya kuingilia, lazima upate ridhaa ya ustaarabu lengwa kadri yawezekanavyo; ikiwa ustaarabu lengwa hawezi kutoa majibu ya kweli kwa sababu ya msongo, basi Kamati ya Maadili ya Kati ya Ndege itafanya hukumu ya &quot;ridhaa iliyofikiriwa&quot; kwa niaba yake</li><li>Njia za kuingilia lazima zichague mpango wenye athari ndogo zaidi kwa ustaarabu lengwa, na kipaumbele kwa kuingilia kwa zisizo za moja kwa moja (kama vile kubadilisha orbit ya asteroid) badala ya kuingilia kwa moja kwa moja (kama vile kushuka moja kwa moja kwa ajili ya uokoaji)</li><li>Wakati wa mchakato wa kuingilia, hufai kuchukua nafasi ya kupata rasilimali au teknolojia ya ustaarabu lengwa</li><li>Baada ya kuingilia kumaliza, lazima uondoke mara moja, na hufai kuacha uwepo wa kudumu katika ndege lengwa</li><li>Baadaye, lazima uwasilishe ripoti kamili ya kuingilia kwa Kamati ya Maadili ya Kati ya Ndege, na kupitia uchunguzi wa maadili</li></ul><h2 id="_4-ufuatiliaji-wa-maadili-na-ushirikiano-wa-ukiukaji" tabindex="-1">4. Ufuatiliaji wa Maadili na Ushirikiano wa Ukiukaji <a class="header-anchor" href="#_4-ufuatiliaji-wa-maadili-na-ushirikiano-wa-ukiukaji" aria-label="Permalink to &quot;4. Ufuatiliaji wa Maadili na Ushirikiano wa Ukiukaji&quot;">​</a></h2><p>Hengyuanzhou imeanzisha &quot;Kamati ya Maadili ya Kati ya Ndege&quot; kama shirika la kujitegemea la ufuatiliaji wa maadili, lenye jukumu la kuunda na kuelezea kanuni za maadili za kati ya ndege, kukubalia miradi ya mwingiliano wa kati ya ndege yenye hatari kubwa, kupokea malalamiko ya ukiukaji wa maadili, na kuchunguza na kufanya hukumu dhidi ya tabia za ukiukaji. Kamati hii inajumuisha wataalamu wa maadili, wataalamu wa sheria, wanasayansi, na wawakilishi wa ustaarabu kutoka kwa rangi anuwai na mazingira ya ufundi anuwai, kuhakikisha utofauti na haki ya maamuzi.</p><p>Tabia zinazovunja kanuni za maadili za kati ya ndege, kulingana na ukubwa wa hali, hatua za ushirikiano zinajumuisha: onyo ya mdomo, laana ya maandishi, kusitisha ufanisi wa mwingiliano wa kati ya ndege, kuondoa leseni ya kuvuka ndege, faini, adhabu ya gerezani, na katika hali za kizungumkuti &quot;ufukuzwe wa ndege&quot; (kuondoa haki ya makazi katika ndege kuu za Hengyuanzhou). Matokeo yote ya ushirikiano wa ukiukaji wa maadili yanarekodiwa katika rekodi za maadili za mtu au shirika, na huhifadhiwa kwa kudumu.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Kanuni za maadili za kati ya ndege ni udhihirisho wa kuzungumzia juu ya maadili ya ustaarabu wa symbiosis wa nanga. Haziondoa tu &quot;nini hifai kufanywa&quot;, bali muhimu zaidi, zinatangaza &quot;nini inapaswa kuwa&quot; — ustaarabu mkubwa kwa kweli sio yule aliyeshinda ustaarabu wangapi, bali yule aliyeheshimu ubinafsi wa ustaarabu wangapi. Katika njia ya Hengyuanzhou inayoelekea kwa symbiosis ya kati ya nyota, kanuni za maadili za kati ya ndege zitadumu kuwa mnara wa taa wa maadili unaoongoza mwelekeo.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>81-Kanuni za Kuvuka Ndege</li><li>87-Kanuni ya Kurudisha Maarifa Tu</li><li>04-Muhtasari wa Msingi wa Kupinga Mauaji</li></ul>',30)])])}const y=i(t,[["render",e]]);export{s as __pageData,y as default};
